CREATE TABLE IF NOT EXISTS products (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, minimum INTEGER NOT NULL CHECK (minimum >= 0), quantity INTEGER NOT NULL DEFAULT 0 CHECK (quantity >= 0), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS movements (id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), kind TEXT NOT NULL CHECK (kind IN ('entrada','saida')), quantity INTEGER NOT NULL CHECK (quantity > 0), note TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT now());